registerRefData('nsw-cond-n-1167',{"id":1167,"pan":null,"ref":"SPP-21-00006","address":"Lot 10 Deposited Plan 27220,Lot 2809 Deposited Plan 1253963,Lot 2810 Deposited Plan 1253963,Lot 2811 Deposited Plan 1253963,Lot 2812 Deposited Plan 1253963,Lot 2813 Deposited Plan 1253963,Lot 2817 Deposited Plan 1253963,Lot 5 Deposited Plan 1190434,Lot 135 Deposited Plan 208203","description":"Subdivision and associated works","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2022-12-07","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSCC-258!20221207T030131.368 GMT","sha256":"ec03a20dae425e690edbb9674e415f76685d2ce491017a1ec42c893f4bdf8dbf","pages":33,"layout":"numbered","n":11,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/1167.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/subdivision-and-associated-works-0","lga":"BLACKTOWN","conditions":[{"label":"1","code":null,"number":"1","title":"PANEL REF - LGA - DA NO. PPSSCC-258 - SPP-21-00006 - Blacktown","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Staged subdivision - stage 1 being 4 residue lots and public roads, stage 2\nbeing 2 residue lots and public roads. Both with associated civil works\nincluding site remediation, tree removal, dam dewatering, importation of\nfill material and landscaping.","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS Lot 10 Deposited Plan 27220","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Applicant: Landcom","text":"Owner: Landcom","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Crown development over $5 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Transport and Infrastructure)\n2021\no State Environmental Planning Policy (Resilience and Hazards) 2021\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021\no State Environmental Planning Policy (Precincts - Central River City)\n2021\no Central City District Plan 2018\no Blacktown Local Strategic Planning Statement 2020\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Blacktown City Council Growth Centre Precincts Development\nControl Plan 2010\n• Planning agreements: Nil\n• Provisions of the Environmental Planning and Assessment Regulation\n2000: Nil [or enter the clauses if relevant]\n• Coastal zone management plan: NIl\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council assessment report: 17 November 2022\n• Written submissions during public exhibition: 0\n• Updated conditions of consent: 5 December 2022","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Briefing: 10 March 2022\no Panel members: Abigail Goldberg (Chair), David Ryan, Chris\nQuilkey\no Council assessment staff: Alan Middlemiss, Luma Araim\n• Final briefing to discuss council’s recommendation: 1 December 2022\no Panel members: Abigail Goldberg (Chair), David Ryan, Moninder\nSingh, Chris Quilkey\no Council assessment staff: Judith Portelli, Alan Middlemiss, Danny\nZablaky, Alex Kwok, Nadeem Shaikh, Tanvir Mazumder, Alison\nCatherine Hewitt, Martin Juleff\no Applicant representatives: Amelia Hawke, Zack Wilson","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION\nApproval, Deferred Commencement Consent. The deferred\ncommencement consent was amended subsequent to the panel meeting\nof 1 December 2022, as reflected in the addendum that is attached to this\nDetermination and Statement of Reasons.","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Draft attached to the council assessment report. Subsequent addendum","text":"received that is attached to this Determination and Statement of Reasons.\nH:\\Planning Panels Secretariat\\02. Project Officer\\01. Syd Central\\01. SCCPP PO Role\\10 November 2022 And 1 December 2022\\Spp-21-00006\nAddendum Conditions Changed[1].Docx 1\nSPP-21-00006 Sydney Central City Planning Panel - addendum\nCondition as shown in\nAttachment 7 submitted\nto the Planning Panel\nRevised draft consent as agreed\nProposed development The words ‘stormwater drainage works’ have been added to the proposed\ndevelopment description\nSection 1 - deferred\ncommencement\nAll conditions in section 1 have been relocated with the applicant’s consent\nto later stages. The recommendation is that the consent is an operational\nconsent, not a deferred commencement consent.\n1.1.1 Relocated to new Condition 7.1.2(i)\n1.1.2 Condition deleted - owner’s consent obtained\n1.1.3 See new Conditions 7.6.1.1 and 10.7.3.1\n1.1.4 See new Condition 10.7.3.4\n1.1.5 See new Condition 7.13/7.13.1\n1.2 Deleted\n2.1.2 New Condition 1.1.2 added as agreed\n2.2.1 Condition amended as agreed to include the words ‘relevant stage in…’ and\n‘relevant’ and condition changed to new Condition 1.2.1\n2.2.3 Agreed new Condition 1.2.3 added\n2.5.1 Agreed new Condition 1.5.1 as modified to reflect that it will be future tree\nplanting, not part of this development application\n3.7.3 Renumbered Condition 2.7.3, this condition requires that Blacktown City\nCouncil is the Principal Certifying Authority for the subdivision.\n3.9.1 Agreed delete reference to ‘temporary drainage works’ (such works are to\noccur on SP2 land). New Condition 2.9.1\n5.4.1 Agreed additional wording ‘…. with any future development application’ to\nreflect that street trees do not form part of this consent. New Condition 4.4.1\n5.5.1.1(d) Revision C replaced with Revision D - agreed. New Condition 4.5.1.1(d)\n5.5.6 New Condition 4.5.6 added as agreed.\n6.3.1 Condition amended as agreed - the amount of fill is 3492m³, not 3300m³.\nNew Condition 5.3.1\n7.2 Deleted. More appropriate at detailed development application stage for\nbuildings\n8.1.2 New condition 7.1.2(i) added as agreed (moved from previous Section 1 -\nDeferred Commencement Consent). Draft Conditions 8.1.2(i) to 8.1.2(xiv)\nbecome 7.1.2(ii) to 7.1.2(xv).\n8.6.1.1 New Condition 7.6.1.1 added as agreed. Relocated from previous Condition\n1.1.3\n8.6.6 Condition deleted as agreed\n8.6.9 New Condition 7.6.8 added as agreed - staging of road construction\nH:\\Planning Panels Secretariat\\02. Project Officer\\01. Syd Central\\01. SCCPP PO Role\\10 November 2022 And 1 December 2022\\Spp-21-00006\nAddendum Conditions Changed[1].Docx 2\n8.11.1 Insert the word ‘temporary’ as agreed in new Condition 7.11.1\n10.1.1 Agreed additional wording in s7.11 contributions condition to ensure that it\nreflects the relevant staging of the development. New Condition 9 (9.1 and\n9.1.1)\n11.1.1 New Condition 10.1.1 graphic deleted. Conditions accurately outline road\nwidths\n11.2/11.2.1 Delete condition as agreed\n11.5/11/5/1 Delete condition as agreed\n11.9.3.4 Delete condition as agreed\nAll conditions Re-numbered due to agreed deletion of, and added, conditions throughout.\nAttachment 7\nSydney Central City Planning Panel report: SPP-21-00006\nConditions of consent (draft)\nProposed development Staged subdivision - stage 1 being 4 residue lots and public\nroads, stage 2 being 2 residue lots and public roads. Both with\nassociated civil works including site remediation, tree removal,\ndam dewatering, stormwater drainage works, importation of fill\nmaterial and landscaping.\nProperty description Lot 10 DP 27220, 93 Schofields Road, Rouse Hill, Lot 2809 DP\n1253963, Schofields Road, Rouse Hill, Lots 2810-2813 DP\n1253963, Cudgegong Road and Schofields Road, Rouse Hill\nand Lot 2817 DP 1253963, Schofields Road, Rouse Hill\n1. ADVISORY NOTES\n1.1 Terminology\n1.1.1 Any reference in this document to a \"consent\" means a \"development consent\" defined\nin the Environmental Planning and Assessment Act 1979.\n1.1.2 Any reference in this consent to a subdivision works certificate or subdivision certificate\nis a reference to a certificate as defined by Section 6.4 of the EP&A Act.\n1.2 Scope of Consent\n1.2.1 The applicant is advised that Council will not release the Subdivision Certificate for the\nrelevant stage in the approved development until such time as the development has\nbeen completed in accordance with all of the relevant conditions of consent, to\nCouncil's satisfaction.\n1.2.2 The granting of this consent does not imply or confer compliance with the requirements\nof the Disability Discrimination Act 1992. The applicant is advised to investigate any\nliability that may apply under that Act. The current suite of Australian Standard 1428 -\nDesign for Access and Mobility, should be consulted for guidance. The prescriptive\nrequirements of Part 1 of the Standard apply to certain buildings requiring development\nconsent.\n1.2.3 Further development consent is required from Council prior to the development of any\nsuper lot and residue lot to be created. In this regard, the applicant shall be required to\nsubmit a development application for any intended lot usage and/or further subdivision.\n1.3 Other Approvals\n1.3.1 The applicant’s attention is drawn to the need to obtain separate appropriate approval\nfor any ancillary development not approved by this consent, including:\n(a) the removal of any tree(s) not indicated on the approved plans and any tree(s)\nlocated greater than 3 m from the building perimeter, and\n(b) any fence, retaining wall, land excavation or filling, advertising structure or other\ndevelopment not being exempt development, and\n(c) demolition of any existing buildings and associated structures in accordance with\nCommented [AM1]: agreed\nthe requirements of State Environmental Planning Policy (Exempt and Complying\nDevelopment Codes) 2008, and\n(d) the installation of vehicular footway crossings servicing the development, and\n(e) the use of any crane that swings over public air space. If a crane is used to\nconstruct this development that swings over public air space, separate Council\napproval under the Roads Act 1993 and Local Government Act 1993 is required.\n1.4 Services\n1.4.1 The applicant is advised to consult with:\n(a) Sydney Water Corporation Limited\n(b) Recognised energy provider\n(c) Natural Gas Company\n(d) The relevant local telecommunications carrier\nregarding any requirements for the provision of services to the development and the\nlocation of existing services that may be affected by proposed works, either on the land\nor on the adjacent public road(s).\nAll approved building construction plans should be submitted to Sydney Water Tap In,\nto determine whether the development will affect Sydney Water’s sewer and water\nmains, stormwater drains and/or easements and if further requirements need to be\nmet. The plans are to be appropriately stamped and all amended plans will require re-\nstamping. For further information go to: www.sydneywater.com.au, then follow the\n“Developing Your Land” link or call 1300 082 746 for assistance.\nSydney Water may also require the applicant to obtain a Trade Waste Approval as part\nof the operation of the approved development. Enquiries should be made to\nascertain the Sydney Water requirements for the eventual operation of the\napproved use.\n1.4.2 Prior to any demolition works, all services or utilities should be disconnected in\nconsultation with the relevant service provider.\n1.4.3 Underground assets may exist in the area that is subject to your application. In the\ninterests of health, safety, and in order to protect damage to third party assets, please\ncontact Dial Before You Dig at www.1100.com.au or telephone on 1100 before\nexcavating or erecting structures (this is the law in NSW). If alterations are required to\nthe configuration, size, form or design of the development upon contacting the Dial\nBefore You Dig service, an amendment to the development consent (or a new\ndevelopment application) may be necessary. Individuals owe asset holders a duty of\ncare that must be observed when working in the vicinity of plant or assets. It is the\nindividual’s responsibility to anticipate and request the nominal location of plant or assets\non the relevant property via contacting the Dial Before You Dig service in advance of any\nconstruction or planning activities.\n1.4.4 The developer shall be responsible for all public utility adjustment/relocation works,\nnecessitated by the above work and as required by the various public utility authorities\nand/or their agents.\n1.4.5 Telstra (and its authorised contractors) is the only company that is permitted to conduct\nworks on Telstra’s network and assets. Any person interfering with a facility or\ninstallation owned by Telstra is committing an offence under the Criminal Code Act 1995\n(Cth) and is liable for prosecution. Furthermore, damage to Telstra’s infrastructure may\nresult in interruption to the provision of essential services and significant costs. If you are\naware of any works or proposed works which may affect or impact on Telstra’s assets in\nany way, you are required to contact Telstra’s Network Integrity Team on 1800 810 443.\n1.5 Tree Planting and Service Locations (After all other services)\n1.5.1 Future street tree planting must not impact on public utilities. The applicant should\nliaise with the relevant service authorities on the location and use of services within the\npublic road reserve. These authorities may be able to lay their services on the opposite\nside of the road, thereby providing larger areas for tree planting.\nStreet tree planting must not interfere with street light spill. In any future development\napplication, the applicant is to provide documentation to confirm there is no conflict\nbetween proposed vegetation at maturity and street lighting.\n1.6 Identification Survey\n1.6.1 The applicant is advised to obtain an identification survey from a registered surveyor to\nascertain the correct location of the property boundaries, and to ensure the\ndevelopment does not encroach upon adjoining properties.\n1.7 Engineering Notes\n1.7.1 All works requiring approval under the Roads Act 1993 or Local Government Act 1993\nmust be approved PRIOR to the Subdivision Works Certification\n1.8 Road Damage\n1.8.1 The cost of repairing any damage caused to Council's assets in the vicinity of the land\nas a result of the development works shall be met in full by the applicant/developer.\n2 GENERAL\n2.1 Scope of Consent\n2.1.1 This consent relates to the following drawings/details submitted to Council with the\nDevelopment Application, subject to compliance with any other conditions of this\nconsent:\nDrawing No. Dated\nSubdivision Plan - Stage 1\nSW_PR144810_DP01\n28 October 2022\nSubdivision Plan - Stage 2\nSW_PR144810_DP02\n28 October 2022\nSubdivision Plan - Staging Plan - Stage 2\nSW_PR144810_DP01 (red highlights)\n28 October 2022\n*Unless modified by conditions of consent\n2.2 Vegetation Management Plan\n2.2.1 The Vegetation Management Plan ‘Rouse Hill Terry Road SINSW VMP Version 4’\ndated 21 July 2022 prepared by Eco Logical Australia and approved by BCC must be\nimplemented.\n2.3 Salinity\n2.3.1 The recommendations made in the Salinity Management Plan (Ref: E24803.E99),\nprepared by EI Australia, dated 27 January 2021, are to be implemented.\n2.4 Acoustic impact\n2.4.1 The recommendations made in the DA Acoustic Assessment (Ref: 20191020.1)\nprepared by Acoustic Logic, dated February 2020, are to be implemented.\n2.5 Services\n2.5.1 Low voltage electricity and telecommunications services for the approved development\nshall be reticulated underground.\n2.6 Suburb Name\n2.6.1 The land the subject of this consent is known to be located in the following suburb.\nThis suburb name shall be used for all correspondence and property transactions:\nSuburb: ROUSE HILL\n2.7 Engineering Matters\n2.7.1 Design and Works Specification\n2.7.1.1 All engineering works required by this consent must be designed and undertaken in\naccordance with the relevant aspects of the following documents except as otherwise\nauthorised by this consent:\n(a) Blacktown City Council's Works Specification - Civil (Current Version)\n(b) Blacktown City Council's Engineering Guide for Development (Current Version)\n(c) Blacktown City Council Development Control Plan (Current Version) including Part\nJ - Water Sensitive Urban Design and Integrated Water Cycle Management\n(d) Blacktown City Council Growth Centre Precincts Development Control Plan\n(e) Blacktown City Council On Site Detention General Guidelines, S3QM online tool\nand standard drawing A(BS)175M\nAny Subdivision Works Certification must also be accompanied by the above documents.\n2.7.1.2 The applicant is required to submit to Council, b onds and/or c ontributions for works\nassociated with the development in conjunction with the civil engineering works required\nto be constructed as part of this development. Works may include:\n• Path paving construction\n• Final layer asphaltic concrete (AC) construction\n• Maintenance of the construction works\n• Removal of temporary infrastructure\nThese matters will be individually addressed within the consent\nNote: A bond release inspection fee will apply.\n2.7.1.3 Prior to release of any bond securities held by Council for civil engineering works, the\npayment of a bond release inspection fee in accordance with Council's Goods and\nServices Pricing Schedule must be made.\n2.7.1.4 Written notice must be provided to adjacent properties, at least 5 days prior to works\ncommencing, where works are approved by this consent and located within Council\ncontrolled lands (i.e. roads, drainage reserves, parks, etc.)\nA copy of this notice must be provided to Council’s Co-ordinator of Engineering\nApproval.\n2.7.2 Other Necessary Approvals\n2.7.2.1 A separate application will be required for the following approvals, under the Local\nGovernment Act 1993 and/or the Roads Act 1993.\n• Works on or occupation of existing public roads (Not including works covered by\na Roads Act Approval)\n• Road and drainage construction and associated works at interface of new Terry\nRd extension and existing Terry Road.\n• Road and drainage construction and associated works at interface of new Terry\nRoad extension and Schofields Road in addition to any works within Schofields\nRoad (i.e. batter works within Schofields Road reserve off proposed Road 3 Ch\n225 to 285).\n2.7.3 Subdivision\n2.7.3.1 Principal Certifier - Blacktown City Council shall be the Principal Certifier for the\nproposed subdivision and issue the Subdivision Certificate.\n2.8 Imported Fill Material\n2.8.1 The only fill material that may be received at the development site is virgin excavated\nnatural material (within the meaning of the Protection of the Environment Operations\nAct1997). Validation of imported material will be required pre-subdivision certificate.\n2.9 Other Matters\n2.9.1 Any future substation or other utility installation required to service the approved\nsubdivision/development shall not be sited on future or existing Council land, including\nroad reservations and/or public reserves.\n2.10 Transport for NSW (TfNSW) Requirements\n2.10.1 The proposed traffic control light at the intersection of Schofields Road/Terry Road/The\nPonds Boulevard to be designed to meet Transport for NSW requirements. The Traffic\nControl Signal (TCS) plans to be drawn by a suitably qualified person and endorsed by\na suitably qualified practitioner.\nThe submitted design to be in accordance with Austroads Guide to Road Design in\nassociation with relevant Transport for NSW supplements (available on\nwww.rms.nsw.gov.au). The certified copies of the signal design and civil design plans\nto be submitted to Transport for NSW for consideration and approval, prior to the\nrelease of a Construction Certificate and commencement of road works.\nDocuments to be submitted to Development.Sydney@transport.nsw.gov.au\nTransport for NSW fees for administration, plan checking, civil works inspections and\nproject management to be paid by the developer prior to the commencement of works.\nThe developer will be required to enter into a Works Author isation Deed (WAD) for the\naforementioned works.\n2.10.2 The redundant driveways on the Schofields Road boundary to be removed and\nreplaced with kerb and gutter to match existing - design and construction of the kerb\nand gutter on Schofields Road to be in accordance with Transport for NSW\nrequirements. Details of these requirements to be obtained by email to\nDeveloperWorks.Sydney@transport.nsw.gov.au\nDetailed design plans of the proposed kerb and gutter to be submitted to Transport for\nNSW for approval prior to the issue of a Construction Certificate and commencement of\nany road works. Documents should be submitted to\nDevelopment.Sydney@transport.nsw.gov.au\nA plan checking fee and lodgement of a performance bond is required from the\napplicant prior to the release of the approved road design plans by Transport for NSW.\n2.10.3 Detailed design plans and hydraulic calculations indicating any changes to the\nstormwater drainage system to be submitted to Transport for NSW for approval, prior to\nthe commencement of any works. Documents should be submitted to\nDevelopment.Sydney@transport.nsw.gov.au\nA plan checking fee will be payable and a performance bond may be required before\nTransport for NSW approval is issued.\n2.10.4 All buildings and structures, together with any improvements integral to the future use\nof the site are wholly within the freehold property (unlimited in height or depth), along\nthe Schofields Road boundary.\n2.10.5 A Construction Traffic Management Plan detailing construction vehicle routes, number\nof trucks, hours of operation, access arrangements and traffic control to be submitted\nto Council for approval prior to the issue of a Certification of Crown works.\n2.10.6 A Road Occupancy Licence to be obtained from the Transport Management Centre for\nany works that may impact on traffic flows on Schofields Road during construction\nactivities. A Road Occupancy Licence can be obtained through\nhttps://myrta.com/oplinc2/pages/security/oplincLogin.jsf\n2.10.7 All vehicles are to enter and leave the site in a forward direction.\n2.10.8 All vehicles are to be wholly contained on site before being required to stop.\n2.10.9 All demolition and construction vehicles are to be contained wholly within the site and\nvehicles must enter the site before stopping. A construction zone will not be permitted\non Schofields Road.\n3 PRIOR TO CONSTRUCTION WORKS (NATURAL AREAS REQUIREMENTS)\n3.1 Vegetation Management Plan\n3.1.1 Annual reports must be provided to Council through the Natural Areas Team.\n3.1.2 Before the conclusion of the maintenance period (i.e. end of Year 5), the Vegetation\nManagement Plan will need to be revised to guide the on-going management of the\nVegetation Management Plan site, including performance criteria for management in\nperpetuity.\n4 PRIOR TO CONSTRUCTION (GENERAL)\n4.1 DA Plan Consistency\n4.1.1 Crown certification for the proposed development shall only be issued when the\naccompanying plans, specifications and/or details are consistent with the approved\nDevelopment Application design plans.\n4.2 Footpath/Road Condition Assessment Fee\n4.2.1 A footpath/road condition assessment fee is to be paid prior to Crown certification. The\napplicable fee will be charged in accordance with Council’s Goods and Services Pricing\nSchedule.\nCouncil will undertake an initial inspection of civil assets outside the development site.\nThe applicant will be held liable for any damage arising from construction activities.\nCouncil will undertake reinstatement works and recover the costs from the applicant,\nwhich will be charged in accordance with Council’s current Goods and Services Pricing\nSchedule in effect at the time of the work.\n4.3 Services/Utilities\n4.3.1 The following documentary evidence shall accompany any Crown Certification:\n(a) A “Notification of Arrangement\" Certificate from a recognised energy provider,\nstating that arrangements have been made with the service authority for electrical\nservices, including the provision of street lighting, to the development.\n(b) A written clearance from Telstra or any other recognised communication carrier,\nstating that services have been made available to the development or that\narrangements have been made for the provision of services to the development.\n4.4 Landscape Architect Requirements\n4.4.1 The applicant to submit landscape plans including street trees for the approval of\nCouncil’s Recreation Planning and Design team with any future development\napplication.\n4.4.2 The applicant to provide 1.5m wide footpath on the road verge adjacent to public open\nspace.\n4.5 Sydney Metro Requirements\n4.5.1 Prior to Construction\n4.5.1.1 All excavation and construction works are to be undertaken in accordance with the\nfollowing:\n(a) Detailed Site Investigation, E24803.E02_Rev1, prepared by ei Australia dated 10\nFebruary 2021.\n(b) Preliminary Site (Contamination) Investigation, R.001.Rev0, prepared by Douglas\nPartners, dated April 2020\n(c) Survey Plan, prepared by RPS, dated 21 August 2019\n(d) Civil Engineering Plans, Revision D prepared by Orion Consulting, dated 5 June\n2020\n(e) Salinity Management Plan, E24803.E99_Rev0, prepared by ei Australia, dated\n27 January 2021.\n(f) Traffic and Transport Study prepared by SCT Consulting, dated 26 November\n2020.\n(g) Landscape Development Application, prepared by place design group and\nLandcom, dated 27 July 2020.\n(h) All documents approved by Sydney Metro under to the deferred commencement\ncondition of this consent.\nsubject to any amendments to those documents required by Sydney Metro in\naccordance with this consent.\nCrown certification must not be issued for the development unless the Applicant has\nsubmitted to Sydney Metro and Sydney Metro has provided written approval of the\nfollowing items:\n(a) Final construction drawings for the Crown certification;\n(b) Revised Risk Assessment - Management Plan addressing the following:\n(c) Compliance with Sydney Metro above ground guidelines\nPrior to the commencement of works, the Certifier must provide written verification to\nSydney Metro that this condition has been complied with.\n4.5.2 Inspections\n4.5.2.1 At any time during the construction of the development, Sydney Metro may give\nreasonable notice to the Applicant or the Applicant’s principal contractor that Sydney\nMetro or persons authorised by that entity seek to:\na) Inspect the development site and all works and structures that may impact on the\nrail corridor, including at specified “hold points” in the construction of the\ndevelopment; and\nb) Attend on-site meetings with the Applicant and its contractors,\nto enable Sydney Metro to determine whether the development has been or is being\nconstructed and maintained in accordance with all approved plans and this\ndevelopment consent.\n4.5.3 Construction\n4.5.3.1 No work is permitted within the rail corridor, or any easements which benefit Sydney\nMetro, at any time, unless the prior approval of, or an Agreement with, Sydney Metro\nhas been obtained by the Applicant. Crown certification must not be issued for the\ndevelopment until written confirmation has been received from Sydney Metro that this\ncondition has been satisfied.\n4.5.3.2 No rock anchors, rock bolts, ground anchors or rock ties, piles, foundations, rock\npillars, transfer structures, basement walls, slabs, columns, beams, cut rock faces, are\nto be installed in the rail corridor, Sydney Metro property or easements. Crown\ncertification must not be issued for the development until it has received written\nconfirmation from Sydney Metro that this condition has been satisfied.\n4.5.4 Documentation\n4.5.4.1 Copies of any certificates, drawings, approvals or documents endorsed by, given to or\nissued by Sydney Metro must be submitted to Council for its records prior to Crown\nCertification.\n4.5.5 General\n4.5.5.1 Any conditions or other requirements imposed by Sydney Metro as part of its\napproval/endorsement of any documents provided by the Applicant to Sydney Metro in\naccordance with these conditions of consent must also be complied with by the\nApplicant when implementing ant approved/endorsed documents, plans, reports during\nthe construction and operation of the development (as applicable).\n4.5.5.2 Where a condition of consent requires Sydney Metro endorsement or approval, Crown\nCertification, as the case may be, until written confirmation has been received from\nthose entities that the particular condition has been complied with. The issuing of\nstaged Crown certification dealing with specific works and compliance conditions can\nonly occur subject to written confirmation from Sydney Metro.\n4.5.6 Adjoining owners\n4.5.6.1 Written permission from the respective owner(s) must be obtained to:\n(a) discharge stormwater onto adjoining owner’s land\n(b) carry out works on adjoining land\n(c) drain the site across land owned by others\nA copy of such written permission shall be lodged with Council.\n5 PRIOR TO CONSTRUCTION (PLANNING)\n5.1 Other matters\n5.1.1 Any required substation as part of the development is required to be located on private\nproperty and incorporated into the design of the building or landscaping of the\ndevelopment. The location of the substation must be endorsed by Council prior to\nCrown certification.\n5.2 Aboriginal Heritage\n5.2.1 If, during the course of construction, the applicant or persons acting on this consent\nbecome aware of any previously unidentified Aboriginal object(s), all work likely to\naffect the object(s) shall cease immediately and the NSW Office of Environment &\nHeritage informed in accordance with Section 89A of the National Parks and Wildlife\nAct 1974. Relevant works shall not recommence until written authorisation from the\nNSW Office of Environment & Heritage is received by the Applicant. In addition, a\nmember of each of the Western Sydney Aboriginal Stakeholder Groups is to be\ncontacted.\n5.3 Imported fill material\n5.3.1 The maximum imported fill material shall not exceed 3,492 m3.\n5.3.2 Clean fill material that is sourced locally and confirmed as being either virgin natural\nmaterial or excavated natural material at the source prior to importation shall be\nimported to the site.\n5.3.3 Truck route for fill material shall only be via arterial roads i.e Windsor, Richmond and\nSchofields Road.\n6 PRIOR TO CONSTRUCTION (ENVIRONMENTAL HEALTH)\n6.1 A qualified acoustic engineer must certify that future applications have been designed\nto minimise the noise intrusion from any external noise source and when constructed\nthe building shall satisfy the following criteria with windows and doors closed:\nInternal Space Time Period Criteria\nLAeq (period)\nLiving Areas Any time 40 dB(A)\nSleeping Areas Day (7am - 10pm) 40 dB(A)\nNight (10pm - 7am) 35 B(A)\nCommented [AH2]: To discuss\nCommented [AM3R2]: Condition to remain. Has been\nresolved\n7 PRIOR TO SUBDIVISION WORKS (ENGINEERING)\n7.1 General\n7.1.1 All relevant conditions within the ‘Prior to Subdivision’ section of this consent shall be\nsatisfied before any Subdivision Works Certificate can be issued.\n7.1.2 The engineering drawings referred to below are not for construction. The Subdivision\nWorks drawings shall be generally in accordance with the approved drawings and\nconditions of consent. Any significant variation to the design shall require a section\n4.55 application\nConstruction /Subdivision works plans shall be generally in accordance with the\nfollowing drawings and relevant consent conditions:\nPrepared By Project No. Drawing\nNo.\nSheet No. Revision Dated\nOrion Consulting 19-0061 DA001 02 C 23/02/2022\nOrion Consulting 19-0061 DA002 02 D 23/02/2022\nOrion Consulting 19-0061 DA003 02 C 23/02/2022\nOrion Consulting 19-0061 DA004 02 A 05/06/2022\nOrion Consulting 19-0061 DA005 02 A 05/06/2020\nOrion Consulting 19-0061 DA006 02 A 05/06/2020\nOrion Consulting 19-0061 DA100 02 C 23/02/2022\nOrion Consulting 19-0061 DA101 02 A 05/06/2020\nOrion Consulting 19-0061 DA200 02 C 23/02/2022\nOrion Consulting 19-0061 DA201 02 B 23/02/2022\nOrion Consulting 19-0061 DA202 02 C 23/02/2022\nOrion Consulting 19-0061 DA300 02 A 05/06/2020\nOrion Consulting 19-0061 DA301 02 A 05/06/2020\nOrion Consulting 19-0061 DA302 02 A 05/06/2020\nOrion Consulting 19-0061 DA303 02 B 23/02/2022\nOrion Consulting 19-0061 DA304 02 A 05/06/2020\nOrion Consulting 19-0061 DA400 02 C 23/02/2022\nOrion Consulting 19-0061 DA401 02 B 23/02/2022\nOrion Consulting 19-0061 DA402 02 C 23/02/2022\nOrion Consulting 19-0061 DA410 02 B 23/02/2022\nOrion Consulting 19-0061 DA411 02 B 23/02/2022\nOrion Consulting 19-0061 DA412 02 B 23/02/2022\nOrion Consulting 19-0061 DA413 02 B 23/02/2022\nOrion Consulting 19-0061 DA414 02 B 23/02/2022\nOrion Consulting 19-0061 DA415 02 B 23/02/2022\nOrion Consulting 19-0061 DA416 02 B 23/02/2022\nOrion Consulting 19-0061 DA417 02 A 23/02/2022\nOrion Consulting 19-0061 DA420 02 A 23/02/2022\nOrion Consulting 19-0061 DA421 02 A 23/02/2022\nOrion Consulting 19-0061 DA422 02 A 23/02/2022\nOrion Consulting 19-0061 DA423 02 A 23/02/2022\nOrion Consulting 19-0061 DA700 02 C 23/02/2022\nOrion Consulting 19-0061 DA701 02 C 23/02/2022\nOrion Consulting 19-0061 DA702 02 C 23/02/2022\nOrion Consulting 19-0061 DA703 02 C 23/02/2022\nOrion Consulting 19-0061 DA704 02 B 23/02/2022\nThe following items are required to be addressed on the Subdivision Works Certificate\nplans:\ni. An easement has been created and registered from the neighbouring property\nowners of Lot 11/DP 27220; Lot 5/DP 1190434; Lot 132/DP 208203 and Lot\n2816/ DP1253963 where trunk drainage line construction and cut or fill batters\nare proposed. The creation is under Section 88B of the Conveyancing Act, 1919\nand registration with NSW Land Registry Services.\nii. Obtain written concurrence from Council’s Manager Asset Design that proposed\nengineering works are consistent with our S7.11 works design prior to issue of\nany Subdivision Works certification. The mark up plan has been saved in\nCouncil’s record system (TRIM No: D22/421911). The applicant needs to\naddress this mark-up plan in preparing any Subdivision work documentation.\nThe engineering plans needs to include S7.11 road and drainage items.\nTherefore, Works In Kind may be possible.\niii. Permanent on lot treatment is required for the R3 zoned residue lots.\nConcurrence from Council Asset Design Team is required for any restriction on\nfuture lots for permanent Stormwater Treatment Measures.\niv. Create drainage easement over drainage works on adjoining land not dedicated\nas drainage reserve. Supporting documents (owners’ consent) needs to be\nprovided for proposed works on adjoining properties.\nv. Include appropriate hydraulic losses and tailwater conditions and resolve design\nissues in areas on mark up plans (TRIM No: D22/421911) as part of the\ndetailed design.\nvi. The proposed road and drainage design need to be consistent with Blacktown\nCity Council. The applicant needs to adopt that future design stages, runoff from\nproposed Residential at Lot 2812 DP 1253963 should be treated by Basin S6.\nThe Gross Pollution Trap S6.1 invert level at CP22W Basin S6 is set at IL\n44.55m Australian Height Datum, top of bioretention basin filter is RL 44.35m\nAustralian Height Datum and top of Gross Pollution Trap diversion weir is\ncurrently set at 45.35m Australian Height Datum. The applicant shall obtain\nconcurrence from Council’s Manager Asset Design for any variation in regard to\nlevels.\nvii. Obtain approvals from Sydney Metro for works within and adjoining its corridor\nand comply with all applicable conditions and requirements.\nviii. Vertical clearance for underpass and barrier system/signage is required for\nsatisfaction to Sydney Metro at Terry Road. Note also the clearance at the local\nroad due to road design needs also to be considered at the north western\ncorner of site.\nix. A Chartered Civil Engineer registered with National Engineers Recognition, is to\ncertify that all the maximum depth of flow in the gutter is less than 200 mm for\nall 1% AEP storm events.\nx. Revised plan of subdivision is to be submitted to Council Planning section to\nreflect appropriate land dedications for Lot 5 in DP 1190434 and Lot 132 in DP\n208203.\nxi. Include Work Asset Diagram with Transport for NSW for amended kerb\nalignment works and associated works at Schofields Rd Intersection and Terry\nRoad extension. Including Road Occupancy Licence.\nxii. The drainage stub at pit 01/01 should be aligned not to clash with future location\nof the kerb ramp.\nxiii. Approval from Council’s S7.11 (Asset Design Team) section is required for any\nclash with S7.11 works in the Contribution Plan with the development.\n(Contribution Plans items S1.3 Works In Kind culvert under road; and\nContribution Plans items RM7 WIK Terry Road extension fronting drainage\nreserve and metro).\nxiv. Tailout works are in Environmental zoned area. Approval from Council native\nvegetation area is required.\nxv. The applicant is to deliver the pedestrian link towards the east of Terry Road\nextension and north of the Sydney Metro rail viaduct. This is to be consistent\nwith approvals currently in place with Craig and Rhodes toward the east of Lot\n134 in DP 208203.\n7.2 Subdivision Works/Construction Requirements\n7.2.1 Under the Environmental Planning and Assessment Act 1979 Crown certification is\nrequired. These works include but are not limited to the following:\n• Road and drainage construction\n• On-site stormwater detention\n• Water quality treatment\n• Earthworks\n• Inter-allotment drainage (created within the subject lot)\n• Path paving (within a subdivision)\nThe above requirements are further outlined in this section of the consent.\n7.3 Local Government Act Requirements\n7.3.1 Under Section 68 of the Local Government Act 1993 an approval for engineering work\nis required. These works include but are not limited to the following:\n• Any works on adjoining land (outside the subject site boundaries)\n• Inter-allotment drainage on adjoining land\nThe above requirements are further outlined in this section of the consent.\n7.4 Roads Act Requirements\n7.4.1 Under Section 138 of the Roads Act 1993 an approval for engineering work is required.\nThese works include but are not limited to the following:\n• Any works within Council’s road reserve\n• Road and drainage construction and associated works at interface of new Terry Road\nextension and existing Terry Road.\n• Road and drainage construction and associated works at interface of new Terry\nRoad extension and Schofields Road in addition to any works within Schofields\nRoad (i.e. batter works within Schofields Road reserve off proposed Road 3 Ch 225\nto 285).\nThe above requirements are further outlined in this section of the consent.\n7.5 Other Engineering Requirements\n7.5.1 If the estimated cost is $25,000 or greater proof of long service levy payment is\nrequired.\n7.5.2 Any ancillary works undertaken shall be at no cost to Council.\n7.5.3 Submit written permission from the affected property owner for any works proposed on\nadjoining land.\n7.5.4 Submit written evidence from Transport for NSW (Roads and Maritime Services)\nindicating compliance with all necessary requirements.\n7.5.5 All street name poles, light poles and bus shelters shall be black powder coated in\naccordance with Blacktown City Council’s Engineering Guide for Development. Ensure\nthis is noted on the construction plans.\n7.5.6 Submit a Public Utilities Plan demonstrating adequate clearance between services to\nstormwater pits, pipes, driveways, light poles, etc.\n7.5.7 If the development is requiring for any Works-in Kind (WIK) agreement then the\nexecution of the WIK agreement shall be provided in writing from Council’s Manager\nAsset Design (Section 7.11).\n7.6 Roads\n7.6.1 Submit a pavement report prepared and designed by a professional civil engineer with\nsoil tests carried out by a registered NATA soils laboratory. The pavement design shall\nwithstand the traffic loadings listed in this consent.\nNote: The design California Bearing Ratio is to be confirmed on site prior to placement\nof any pavement. If actual CBR is less than design California Bearing Ratio, revised\npavement design will be required.\n7.6.1.1 Any approved drawing must show a 5m x 5m splay for residential allotments at each\nstreet intersection.\n7.6.2 Submit a traffic management plan including but not limited to a Traffic Control Plan and\nPedestrian Management Plan, for any works within public road reserves. The Traffic\nControl Plan shall be approved, signed and dated by a person who holds a current\nRoads and Maritime Services (RMS) Work Zone Traffic Management Plan\naccreditation and photo card.\n7.6.3 Proposed new roads shall be designed and constructed as follows:\nName Width(m) Length\n(m)\nFormation (m) Traffic Loading\nN(E.S.A)\nRoad No.1 19 165 4.5-11-3.5 5x10^5\nRoad No.2 9 (half width) 216 3.5-5.5 5x10^5\nRoad No.3 (CH 00.00\nto CH 225.00)\n9 (half width) 225 5x10^5\nRoad No.3 (CH\n225.00 to CH 295.00)\n18 70 3.5-11-3.5 5x10^5\nRoad No.4 19 70 4.5-11-3.5 5x10^5\nRoad No.5 9 (half width) 211.5 3.5-5.5 5x10^5\nTerry Rd (extension) 20 and Variable* 420 4.5-11-4.5 and\nVariable*\n1x10^6\n*Note Terry Road extension is a collector road with general formation 4.5m verge-11m\ncarriageway and 4.5m verge. Road reserve width and carriageway formation from\nchainage 135.00 to connection with Schofields Road is to generally be in accordance\nwith engineering plans prepared by Orion Consulting Pty Ltd plan reference No. 19-\n0061, plan No.201, revision B and dated 23/02/2022. Prior to release of any\nsubdivision works certification and/or Roads Act Approval for Terry Road (extension)\ninterfacing with Schofields Rd, the applicant shall obtain the necessary concurrence\nfrom Transport for New South Wales (Roads and Maritime) as detailed within this\nconsent.\n7.6.4 Half width road with a minimum 4.5 m width of pavement for the full road frontage of\nthe development is required. These construction works include drainage, kerb and\ngutter, footway turfing, service adjustments and any other ancillary work necessary to\nmake this construction effective.\n7.6.5 Existing roads shall be designed and re-constructed as follows:\nName Width (m) Length (m) Formation (m) Traffic\nLoading\nN(E.S.A)\nTerry Road 20 50 4.5-11-4.5 1x10^6\n7.6.6 Design the roundabout in accordance with Austroads “Guide to Traffic Engineering\nPractice - Roundabouts Part 6” and to Council’s standard. The roundabout shall be\nconstructed at the intersection of Terry Rd (extension) and Road No.1.\n7.6.7 Suitable traffic circulation in the form of temporary turning heads (in accordance with\nCouncil Engineering Guide for Development - section 3.27 Temporary Turning Heads)\nin dead end roads are to be provided. I.e. within Road No.5 - note the proposed\ntemporary turning head will need to be amended to meet Council’s requirements.\n7.6.8 Staging of road construction will be permitted where suitable traffic circulation or\ntemporary turning areas in dead end roads are evident in accordance with Council’s\nEngineering Guide for Development.\n7.7 Drainage\n7.7.1 Drainage from the site must be connected into Council’s existing drainage system.\n7.7.2 Provide inter-allotment drainage and associated easement in gross to drain water, to\nthe benefit of Blacktown City Council, where stormwater drainage does not drain\ndirectly to a public road. i.e. stormwater discharge into Lot 11 in DP 27220 as well as\nLots 2815, 2816, 2813 and 2811 in DP 125963.\n7.7.3 Any overland or stormwater flows must be intercepted at the property boundary,\nconveyed through the site in a piped or channelled drainage system and discharged in\na satisfactory manner.\n7.8 Signage and Line Marking\n7.8.1 A formal submission must be made to the Local Traffic Committee (LTC) through\nCouncil’s Traffic Engineering department for all signage and line marking details\nproposed as part of these works.\nA determination will be required prior to the implementation of all signage and line\nmarking works.\nMust include but not be limited to:\n- the entire site\n- roundabout\n- underpass and clearance signage/crash barriers if required.\n- intersection of Terry Road extension and Schofields Road\n7.9 Erosion and Sediment Control\n7.9.1 Provide a sediment and erosion control plan in accordance with Council's Soil Erosion\nand Sediment Control Policy and Engineering Guide for Development.\n7.10 Earthworks\n7.10.1 Proposed lots must be filled so that the ground levels behind the building are a\nminimum of 500mm above the designed 100-year average recurrence interval flood\nlevel.\n7.10.2 Batters are not to exceed a grade of 1V:5H and are to be stabilised with topsoil, turf\nand vegetation.\n7.10.3 Finished levels of all internal works at the road boundary of the property must be 4%\nabove the top of kerb.\n7.11 Temporary Stormwater Quality Control (Roads)\n7.11.1 A temporary stormwater quality treatment system shall be designed in accordance with\nCouncil’s Engineering Guide for Development and DCP Part J - Water Sensitive Urban\nDesign and Integrated Water Cycle Management for treatment of stormwater runoff\nfrom the new roads.\n7.11.2 Provide a maintenance schedule for the stormwater quality device that is signed and\ndated by the designer.\n7.12 Footpaths\n7.12.1 Path paving is to be provided generally in accordance with Council’s Path Paving\nPolicy, Blacktown City Council Engineering Guide for Development and Blacktown City\nCouncil Growth Centre Precincts Development Control Plan 2010.\n7.12.2 Construct shared user paths (including signage and linemarking) in accordance with\nPart 6A (Paths for Walking and Cycling) 2017 of Austroads “Guide to Road Design”\nand the RMS NSW Bicycle Guidelines - July 2005, as follows:\n7.13 Dam Dewatering\n7.13.1 The Dam Dewatering Plan must be prepared by a suitably qualified aquatic ecologist\nand must include the following recommendations and information:\n• That a fauna survey will be conducted prior to dam dewatering.\n• Proposed relocation sites for native species. Additional release points must be\nconsidered if large numbers of predatory fish (e.g. Long-finned Eels) are\nrecovered.\n• Identification of the licence details required under the Fisheries Management Act\n1994 and / or the Biodiversity Conservation Act 2016.\n• Methods to prevent injury to fauna during pumping of water from the dam.\nStreet Name Side Cycle-way Width (m) Length\nTerry Road Extension\nRoad 1 and Road 4\nEast 2.5 Full length\n• Details of how exotic pest species will be humanely euthanised in a manner\nconsistent with the Prevention of Cruelty to Animals Act 1979.\n• Methods for disposing of dam water and preventing the spread of carp eggs,\njuvenile pest species or eggs into the catchment and natural waterways.\n• Details on how fauna will be rescued from dam sediments or allowed to relocate\nfrom the dam.\n• Details of the appropriate timing (season) for dewatering.\n• Details on reporting of actions undertaken with tallies of fauna removed from the\ndam with details of their relocation destination (or destruction).\n• Details on dealing with unexpected threatened species finds e.g. Green and\nGolden Bell Frog. The procedure must include, as a minimum, the following:\ni. stop work arrangements in the immediate area of the threatened species;\nii. notification and communication protocol;\niii. consultation with the specialists to assess the significance of the find; and\niv. a list of approvals, licences or permits likely required prior to\nrecommencing works.\n• Discharge limits as per relevant Australian and New Zealand Environment and\nConservation Council water quality guidelines\n• Prior to any work commencing, an Aquatic Ecologist is to be appointed and their\ndetails (name, qualifications, phone and email) provided to Council.\n• The Aquatic Ecologist is to be present during all Dam Dewatering\n• If the Aquatic Ecologist is replaced, Council is to be notified in writing of the\nreason and the details of the new Project Ecologist within 7 days.\n• Within 7 days of the works, the aquatic ecologist is to provide a report on the\nworks, to Council through the Natural Areas Team\n8 DURING CONSTRUCTION (ENGINEERING)\n8.1 Notification of Works\n8.1.1 A written notification of works must be submitted to Council’s Engineering Approvals\nTeam prior to the commencement of any engineering works required by this consent.\nThis must be submitted a minimum 5 business days prior to commencement of\nengineering works.\n8.2 Insurances\n8.2.1 Current copies of relevant insurance Certificates of Currency are to be submitted to\nCouncil’s Engineering Approvals Team. This shall be submitted prior to\ncommencement of engineering works required by this consent that are carried out on\nCouncil controlled lands such as roads, drainage reserves and parks. This includes\nPublic Liability Insurance with a minimum of $20,000,000 Indemnity and Workers\nCompensation.\n8.3 Boundary Levels\n8.3.1 Any construction at the property boundary, including but not limited to fences, retaining\nwalls and driveways shall not be carried out until boundary alignment levels have been\nfixed.\n8.4 Tree Protection and Preservation\n8.4.1 Existing vegetation and trees shall be left undisturbed except where roads, stormwater\ndrainage infrastructure, site filling and/or building works are proposed.\n8.4.2 There is to be no storage of materials, stockpiling of excavated material or parking of\nplant/machinery within the drip line of the crown of any retained trees.\n8.5 Soil Erosion and Sediment Control Measures\n8.5.1 Soil erosion and sediment control measures onsite shall be implemented, maintained\nand monitored in accordance with Council's Soil Erosion and Sediment Control Policy.\n8.5.2 Re-vegetation and restoration of all disturbed areas as a result of the development\nworks shall be completed as soon as practicable after the completion of earthworks\nand before the commencement of any other works on-site. The revegetated/restored\nareas must be established prior to the release of maintenance security/bonds. Note: All\nopen drains must be turfed.\n8.5.3 All required soil erosion and sedimentation control measures are to be maintained\nthroughout the entire construction period and until all disturbed areas are restored to\nthe satisfaction of Council in accordance with the design and construction specification.\nInfringement Notices incurring a monetary penalty may be issued by Council where the\nmaintenance of measures is deemed inadequate.\n8.6 Filling of Land and Compaction Requirements\n8.6.1 Suitable land fill replacement is required when unsuitable soils are removed. All fill\nincluding existing fill shall be compacted in accordance with Council's Works\nSpecification - Civil (current version). A compaction certificate shall be obtained from\nan appropriately qualified practising registered engineer (NER) verifying that the correct\ncompaction requirements have been met. This compaction certificate is to be submitted\nto Council.\n8.6.2 Special attention is drawn to the below listed requirements of Council's Works\nSpecification - Civil (Current Version).\na) Compaction certificates for fill within road reserves.\nb) Compaction certificates for road sub-grade.\nc) Compaction certificates for road pavement materials (sub-base and base\ncourses).\nd) Contour lot fill diagrams and lot fill compaction certificates. A restriction as to\nUser with Council's standard wording must be placed on filled lots.\ne) Applicant to submit material compliance documentation in accordance with\nCouncil’s Civil Works Specification 8.1.4\n• Compliance Certificate and Test Results\n• Delivery Dockets\n• Summary of Material deliveries as per template available on Council’s\nwebsite\nNote: Council's Works Specification (Civil) requires road pavement and pipe bedding\nmaterials be sourced from N.A.T.A. certified stockpiles.\nThe above documentation shall be submitted prior to release of the Subdivision\ncertificate as required by this consent.\n8.6.3 Site filling within lot boundaries (not in road reserves) and compaction is to be carried\nout under the supervision of a Chartered Geotechnical Engineer and shall be in\naccordance with Blacktown City Council's “Works Specification - Civil (Current\nVersion)”. Minimum standard compaction of 95% must be achieved and certified by a\nNATA registered soils lab and details submitted to Council.\n8.6.4 Only clean fill shall be deposited/imported on site in accordance with Council's Works\nSpecification - Civil (Current Version). All fill material imported to site shall be classified\nas Virgin Excavated Natural Material (VENM). Validation of the imported fill material will\nbe required by a suitably qualified registered engineer.\n8.6.5 Appropriate dust control measures are to be implemented during construction to\nreduce any impact on local air quality and reduce dust emissions. This will include but\nnot be limited to regularly wetting down of the site during the course of works being\ncarried out in order to control wind-blown dust.\n8.6.6 All roads adjoining the site must be kept clean and free of all materials. Infringement\nNotices incurring a monetary penalty may be issued by Council where this measure is\nnot being complied with.\n8.6.7 Trucks transporting cut and fill must have their loads covered and provisions of “shaker\npads” and wash-down areas for trucks leaving the site are to be made available. All\ndetails are to be shown on soil erosion and sediment control plans.\n8.6.8 Prior to the placement of any fill on the site all topsoil and vegetation must be removed\ndown to a suitable sub-grade material. The topsoil is to be stockpiled for use in\nrevegetation of the site.\n8.7 Inspection of Engineering Works - Environmental Planning and Assessment Act\n1979\n8.7.1 Comprehensive inspection compliance certificate(s) to be issued for all engineering\nworks required by this consent and the approved construction certificate. The\ninspection compliance certificate(s) can only be issued by Council or an accredited\ncertifier, under Part 4A of the Environmental Planning and Assessment Act 1979 as\namended. A schedule of mandatory inspections is listed in Council’s Works\nSpecification - Civil (current version).\n8.8 Inspection of Engineering Works - Roads Act 1993 or Local Government Act\n1993\n8.8.1 All inspection(s) required by this consent for any engineering works that are approved\nunder the Roads Act 1993 or Local Government Act 1993 must be made by Council's\nDevelopment Overseers.\nInspections must be pre-booked with a minimum 24 hours’ notice. Council’s\nDevelopment Overseers may be contacted on 02 9839 6586 between 6 am - 7 am,\nMonday to Friday. Note: A site inspection is required prior to commencement of work.\nA schedule of mandatory inspections is listed in Council’s Works Specification - Civil\n(current version).\n8.9 Public Safety\n8.9.1 The applicant is advised that all works undertaken are to be maintained in a safe\ncondition at all times. Council may at any time and without prior notification make safe\nany such works Council considers to be unsafe and recover all reasonable costs\nincurred from the applicant.\n8.10 Site Security\n8.10.1 Chain wire gates and security fencing must be provided around the site in order to\nprevent unauthorised access and dumping of rubbish.\n8.11 Traffic Control\n8.11.1 Any \"Traffic Control Plan\" utilised for engineering works required by this consent must\nbe prepared by a person who holds a current Roads and Maritime Services (RMS)\nWork Zone Traffic Management Plan accreditation and photo card for all works that are\ncarried out in or adjacent to a public road. This Plan must satisfy all the requirements of\nAS 1742.3 - 2009.\n8.11.2 Traffic control devices/facilities (i.e. barricades, signs, lights, etc.) required by the\ncertified Traffic Control Plan must be setup, installed, monitored and maintained and by\na person who holds a current Roads and Maritime Services (RMS) accreditation and\nphoto card to implement Traffic Control Plans.\n8.11.3 Persons undertaking the control of traffic through or around work sites on Council\ncontrolled roads must hold a current Roads and Maritime Services (RMS) Traffic\nController accreditation and photo card and carry it with them.\n8.11.4 The applicant is advised that prior to implementation of any traffic control system and\nduring the entire course of construction suitably qualified Roads and Maritime Services\n(RMS) accredited work site traffic controllers will ensure a smooth transition with other\nnearby traffic control setups. The coordination, communication and cohesion between\nadjacent traffic control systems shall be addressed by the applicant and must satisfy all\nthe requirements of AS 1742.3 - 2009.\n8.11.5 Where the Traffic Control Plan may change during the course of construction to\nfacilitate new works, a revised traffic control plan shall be prepared and certified by a\nperson who holds a current Roads and Maritime Services (RMS) accreditation to\nprepare a Work Zone Traffic Management Plan. This Plan must satisfy all the\nrequirements of AS 1742.3 - 2009 and the current version of the RMS Traffic Control\nat Work Sites manual and shall be submitted to Council prior to implementation.\n8.12 Powder Coated Furniture\n8.12.1 Where the conditions of this consent permit the installation of powder coated furniture\n(i.e. street lighting poles, bus shelters, rubbish bins, seats or any other items of street\nfurniture), a certificate from the manufacturers shall be provided to Council confirming\nthat the nominated powder coated items have been prepared and coated in\naccordance with Australian Standard AS/NZ 4506-2005 (service condition category 3).\nThis certificate must be no more than 3 months old and shall be provided to Council\nprior to the installation of the relevant items of the street furniture. Any items of street\nfurniture not so certified shall be removed and replaced at no cost to Council with items\nappropriately certified.\n8.13 Road Line Marking and Traffic Signage\n8.13.1 Prior to the implementation of any road line marking and traffic signage required by this\ndevelopment the applicant shall acquire an approved construction certificate for the line\nmarking and traffic signage plan arrangement.\nIn this regard, the applicant shall provide evidence to the certifying authority in order to\ndemonstrate that the proposed line marking and traffic signage plan has approval from\nthe local traffic committee and has been adopted by Ordinary Council Meeting.\nNote: all recommendations by the local traffic committee and Ordinary Council Meeting\nshall be reflected within the construction certificate for line marking and traffic signage.\n8.14 Other Matters (Drainage)\n8.14.1 The 200-micron Ocean Guards by Ocean Protect in the street pits are not to be\nreduced in size nor replaced with an alternate manufacturer’s product.\n8.15 Environmental Health requirements\n8.15.1 Any asbestos material is to be handled and treated in accordance with the WorkCover\ndocument “Your Guide to Working With Asbestos - Safety guidelines and requirements\nfor work involving asbestos” dated March 2008.\n8.15.2 Any materials requiring off-site disposal will need to be classified, managed and\ndisposed of in accordance with the Protection of the Environment Operations Act 1997\nand the NSW Environment Protection Authority’s Waste Classification Guidelines\n(2014)\n9 PRIOR TO SUBDIVISION CERTIFICATE - PLANNING\n9.1 Section 7.11 Contributions under Section 7.17 Directions\n9.1.1 The following monetary contributions under Section 7.11 of the Environmental Planning\n& Assessment Act 1979 must be paid. The amounts below are as 25 August\n2022. They WILL BE INDEXED from this date to the date of payment. Payment of the\nindexed amounts must be made prior to the issue of a Construction Certificate (for\nbuilding works) or Subdivision Certificate (for subdivision works) either by Council or\nany accredited certifier, whichever occurs first for the relevant stage.\nPLEASE NOTE: Indexed payments must be made by BANK CHEQUE IF IMMEDIATE\nCLEARANCE IS REQUIRED and payments made by credit card or EFTPOS attract a\n0.5% surcharge.\nContribution Item Amount\nStormwater Quantity\nSecond Ponds Creek Land $1,895,669.00\nSecond Ponds Creek Works $273,398.00\nStormwater Quality\nSecond Ponds Creek all other\ndevelopment\n$378,259.00\nTotal $2,547,326.00\nDevelopable Area: 5.2150 hectares\nThe contribution(s) will be indexed according to the Australian Bureau of Statistics'\nConsumer Price Index (Sydney Housing) or Consumer Price Index (All Groups\nSydney).\nCopies of the following relevant Contributions Plan(s) may be inspected/purchased\nfrom Council's Information Centre, or viewed/downloaded at www.blacktown.nsw.gov.au:\nS7.11 CP No. 22 - Rouse Hill (Works and Land)\nThe Section 7.11 contribution(s) have been based on the total developable area, the\nsite's road frontage and the potential additional population nominated below. Should\nthe final plan of survey indicate any change in the total developable area or should\namendments change the potential additional population, the Section 7.11\ncontribution(s) will be adjusted accordingly.\n9.2 Special Infrastructure Contribution\n9.2.1 A special infrastructure contribution is to be made in accordance with the\nEnvironmental Planning and Assessment (Special Infrastructure Contribution -\nWestern Sydney Growth Areas) Determination 2011 (as in force when this consent\nbecomes operative).\nMore information\nInformation about the special infrastructure contribution can be found on the\nDepartment of Planning’s website:\nhttp://www.planning.nsw.gov.au/PlanningSystem/DevelopmentContributionsSystem/tab\nid/75/guage/en-US/Default.aspx\nPrior to the issue of any Subdivision Certificates, evidence that the special\ninfrastructure contribution payment has been made is to be submitted to Council.\nPlease contact the Department of Planning and Environment regarding arrangements\nfor the making of a payment.\nNote: This condition is for information purposes only.\n9.3 Service Authority Approvals\n9.3.1 The following documentary evidence shall be obtained and forwarded to the Principal\nCertifying Authority prior to the release of the Subdivision Certificate:\n(a) A Section 73 Compliance Certificate under the Sydney Water Act 1994 must be\nobtained. Please refer to the \"Building Plumbing and Developing\" Section of the\nwebsite www.sydneywater.com.au, then follow the \"Developing Your Land\" link\nor telephone 13 20 92 for assistance. Following application, a \"Notice of\nRequirements\" will advise of water and sewer extensions to be built and charges\nto be paid. Please make early contact with the Coordinator since building of\nwater/sewer extensions can be time consuming and may impact on other\nservices and building, driveway or landscape design. The Section 73 Certificate\nmust be submitted to the Principal Certifying Authority prior to the release of the\nplan of subdivision.\n(b) A “Notification of Arrangement\" Certificate from a recognised energy provider,\nstating that arrangements have been made with the service authority for\nelectrical services, including the provision of street lighting, to the development.\n(c) A written clearance from Telstra or any other recognised communication carrier,\nstating that services have been made available to the development or that\narrangements have been made for the provision of services to the development.\n9.4 Consent Compliance\n9.4.1 A Subdivision Certificate shall not be issued until all conditions of this consent have\nbeen satisfied.\n9.5 Salinity\n9.5.1 A detailed salinity assessment report for all roads in each stage prepared by a suitable\nqualified person shall be prepared and submitted to Council’s satisfaction prior to the\nsubdivision works. The recommendations of the salinity assessment are to be identified\non the construction plans and implemented during construction.\n9.6 Site Validation Contamination\n9.6.1 A site validation contamination report for all roads in each stage prepared by a suitable\nqualified geoscientist shall be prepared and submitted to Council’s satisfaction prior to\nsubdivision works confirming validation to residential standard in National\nEnvironmental Protection Measure Guidelines amended 2013.\n9.7 Section 88B\n9.7.1 A restriction as to User over each proposed residue lots shall be created under Section\n88B of the Conveyancing Act 1919 in the following terms:\nNo further development of the lot burdened is to take place unless it is approved by\ndevelopment consent. Such approval is likely to require, but not be restricted to,\nconstruction of road and drainage works, the provision of lot fill and the payment of\nSection 7.11 Contributions.\nNOTE: The final wording of the recital of the Restriction as to User is to be to Council's\nsatisfaction.\n10 PRIOR TO SUBDIVISION ENGINEERING\n10.1 Site Access\n10.1.1 There shall be no direct vehicular or pedestrian access to and/or from the following\nnominated road(s) for any lots having frontage to that road. An appropriate restriction\non the use of land shall be created under Section 88B of the Conveyancing Act 1919\ncovering this requirement. The Section 88B Instrument shall contain a provision that it\nmay not be extinguished or altered except with the consent of Blacktown City Council.\nNominated Road(s): Terry Road and Schofields Road\n10.1.2 All lots shall have access from a dedicated public road. In this regard, all proposed\nroads shall be dedicated as public road free of cost to Council.\n10.1.3 Any future substation or other utility installation required to service the approved\nsubdivision/development shall not under any circumstances be sited on a future public\nroad. Any proposal to locate a proposed substation or other utility installation on a\nfuture public road shall be negotiated with and fully endorsed by the relevant Council\nDirectorates.\n10.2 Road Damage\n10.2.1 The cost of repairing any damage caused to Council's assets in the vicinity of the\nsubject site as a result of the development works be met in full by the\napplicant/developer.\n10.3 Security\n10.3.1 An acceptable security (bond) guaranteeing the future completion of the road sealing\nworks shall be lodged with Council. The bond amount is to be calculated at the\nasphaltic contribution rate current at the time and is to be accompanied by Council’s\nstandard Deed of Agreements for Bonds.\n10.3.2 The manufacturer of the light poles/street name poles/bus shelters is to provide written\ncertification that all structures have been black powder coated to the satisfaction of\nCouncil's Development Services Engineers prior to installation.\n10.4 Consent Compliance\n10.4.1 A Subdivision Certificate shall not be issued until all conditions of this consent have\nbeen satisfied.\n10.5 Additional Inspections\n10.5.1 Any additional Council inspection services provided beyond the scope of any\nCompliance Certificate or inspection package and required to verify full compliance\nwith the terms of this consent, will be charged at the individual inspection rate\nnominated in Council’s Fees and Charges Schedule and shall be paid to Council.\n10.6 Other Matters (Drainage)\n10.6.1 A Chartered Civil Engineer registered with National Engineers Recognition, is to certify\nthat:\ni. all the requirements of the approved drainage plan have been undertaken;\nii. The 200 micron OceanGuards have been installed in the street pits as per the\napproved plan;\niii. the maximum depth of flow in the gutter is less than 200 mm for all 1% Annual\nExceedance Probability storm events;\niv. a copy of the certification and the works-as-executed drainage plan has been\nprovided to the certifier, who shall provide it to Council.\n10.6.2 EASEMENTS/RESTRICTIONS/POSITIVE COVENANTS\n10.6.2.1 Provide a Positive Covenant over each lot for future development to provide water\nquality for the entire site in accordance with the following target requirements:\nRequired percentage reductions in post development average annual load of pollutants\nPollutant % post development pollutant reduction targets\nGross Pollutants 90\nTotal Suspended Solids 85\nTotal Phosphorous 65\nTotal Nitrogen 45\n10.6.2.2 The Positive Covenant must be registered with NSW Land Registry Services.\nProvide a Positive Covenant over each lot for future development to have a Stream\nErosion Index of 3.5 or less. The Positive Covenant must be registered with NSW Land\nRegistry Services.\n10.6.3 OTHER DRAINAGE MATTERS\n10.6.3.1 Written evidence is to be provided that the developer/owner has entered into and\nprepaid a minimum six years signed and endorsed maintenance contract with Ocean\nProtect for the maintenance of the 200 micron OceanGuards after installation in all the\nstreet pits (including Terry Road extension), in accordance with the following:\ni. an initial inspection of the site to verify the number of OceanGuards and that\nthe OceanGuards are all correctly installed and not damaged.\nii. where OceanGuards are missing, not properly installed or damaged, include\nthe cost of rectification.\niii. provision for 4 cleans per year for the first 2 years;\niv. provision for 3 cleans per year thereafter;\nv. replacement of the 200 micron bags at 2 years and 4 years ;\nvi. complete removal of the temporary OceanGuards and their associated\nframes from the street pits at the end of the 6 year period;\nvii. the estimate shall include allowances for CPI and a 15% allowance for\npossible damage to the devices by third parties.\nviii. Report annually on maintenance undertaken to Council’s Water Sensitive\nUrban Design Compliance Officer at WSUD@blacktown.nsw.gov.au\nix. Forward a copy of the signed and endorsed contract and evidence of\npayment to Council’s WSUD Compliance Officer at\nWSUD@blacktown.nsw.gov.au. This contract cannot be cancelled.\n10.7 Engineering Matters\n10.7.1 Surveys/Certificates/Works As Executed plans\n10.7.1.1 A Work-as-Executed plan signed by a Registered Engineer or a Registered Surveyor\nmust be submitted to Council when the engineering works are completed, in a colour\nsoftcopy format (.PDF). All engineering Work-as-Executed plans MUST be prepared\non a copy of the original, Crown certification plans for engineering works (including\nworks under the Roads Act 1993 and the Local Government Act 1993 covered by this\ndevelopment application).\n10.7.1.2 A Work-as-Executed plan for any S7.11 infrastructure works signed by a Registered\nEngineer or a Registered Surveyor must be submitted to Council when the\nengineering works are completed, in a colour softcopy format (.PDF). All engineering\nWork-as-Executed plans MUST be prepared on a copy of the original, Crown\nCertification plans for engineering works (including works under the Roads Act 1993\nand the Local Government Act 1993 covered by this Development Application).\n10.7.1.3 A Certificate shall be submitted by a Registered Surveyor indicating that all pipelines\nand associated structures lie wholly within any easements required by this consent.\n10.7.1.4 A certificate from a Registered Engineer (NER) must be obtained and submitted to\nCouncil verifying that the constructed Stormwater Quality Control system will function\neffectively in accordance with Blacktown Council’s DCP Part J - Water Sensitive\nUrban Design and Integrated Water Cycle Management.\n10.7.1.5 Written evidence is to be obtained from Transport for NSW (Roads and Maritime)\nindicating compliance with its requirements including the payment of any necessary\nworks supervision fees.\n10.7.1.6 Written evidence is to be obtained from Sydney Metro (Rail Authority) indicating\ncompliance with its requirements including the payment of any necessary works\nsupervision fees.\n10.7.1.7 Applicant to submit the following in accordance with Council's Works Specification -\nCivil (Current Version):\na) Compaction certificates for fill within road reserves.\nb) Compaction certificates for road sub-grade.\nc) Compaction certificates for road pavement materials (sub-base and base\ncourses).\nd) Contour lot fill diagrams and lot fill compaction certificates. A restriction as to\nUser with Council's standard wording must be placed on filled lots.\ne) Applicant to submit material compliance documentation in accordance with\nCouncils Civil Works Specification 8.1.4\n• Compliance Certificate and Test Results\n• Delivery Dockets\n• Summary of Material deliveries as per template available on Council’s\nwebsite.\n10.7.1.8 The applicant is to submit the certified approved line marking and traffic signage plan\nas required by this consent. This will require evidence to demonstrate that approvals\nhave been obtained from the Local Traffic Committee and adoption by Council\nOrdinary Meeting. A final inspection report is to be included noting that all line\nmarking and traffic signage works are complete.\n10.7.1.9 The submission to Council of Compliance Certificate(s) and construction inspection\nreports required by this consent for engineering works. A final inspection report is to\nbe included noting that all works are complete.\nWhere Council has been nominated or defaulted as the nominee for engineering\ncompliance, final inspections can be arranged through Council’s Coordinator of\nEngineering Approvals contactable on (02) 9839 6263. A final inspection checklist\nmust be completed by the applicant prior to the final inspection.\nNote: Practical Completion issued by Council’s Asset Construction team will be\nrequired for any S7.11 works under relevant Work-in-Kind agreement.\n10.7.1.10 A survey report prepared and signed by a Registered Surveyor providing confirmation\nof the depth of all constructed road pavements in the form of finished surveyed levels\nfor each road pavement layer, noting tolerances for any variations in constructed\npavement depth.\n10.7.1.11 Structural certification ‘as built’ by a qualified Engineer for all structural items\napproved by the scope of this consent. This includes but is not limited to the following\ncomponents:\na) Non-standard stormwater pits\nb) Culverts\nc) Any other structural elements\n10.7.1.12 A certificate or letter signed by an appropriately qualified professional, indicating that\nall pre-cast pits/culverts have been specifically designed and manufactured for the\nproject in accordance with the approved civil plans (specific reference required) and\nthe necessary Australian Standards.\n10.7.1.13 A Certificate shall be submitted by a suitably qualified geotechnical engineer verifying\nthat any fill material imported to site is virgin excavated natural material (VENM).\n10.7.2 Easements/Restrictions/Positive Covenants\n10.7.2.1 Any covenant, easement or restriction created as a result of this consent must be in\naccordance with the following:\n(a) Blacktown City Council's standard recitals for Terms of Easements and\nRestrictions (Current Version).\n(b) The standard format for easements and restrictions as accepted by NSW Land\nRegistry Services\n10.7.2.2 Restrictions and positive covenants must be endorsed by Council and lodged with\nNSW Land Registry Services (LRS) over the overland flow-path. Documentary\nevidence of this lodgement shall be submitted to Council.\n10.7.2.3 The creation of an Easement in Gross to Drain Water, with a minimum width in\naccordance with Council’s Engineering Guide for Development (current issue), to the\nbenefit of Blacktown City Council over the following nominated lot(s) free of cost to\nCouncil. The easement must be created under the Conveyancing Act 1919 and have\nthe nominated lot(s) burdened and each and every lot upstream benefited.\nNominated Lot(s) Burdened: All lots affected by stormwater infrastructure from Road\nNo.1. This includes Lot 11 in DP 27220 as well as Lots 2815, 2816, 2813 and 2811 in\nDP 125963.\n10.7.2.4 All relevant Section 88B restrictions and covenants created, as part of this consent\nshall contain a provision that they cannot be extinguished or altered except with the\nconsent of Blacktown City Council.\n10.7.3 Dedications\n10.7.3.1 Dedication at no cost to Council of 5 m x 5 m splay corners on lots at each street\nintersection.\n10.7.3.2 Dedication at no cost to Council splay corners at the Roundabout (intersection of\nTerry Road extension and Road No.1/Road No.4 to the satisfaction of Council’s\nSenior Coordinator Engineering Approvals and generally in accordance with the\napproved design.\n10.7.3.3 Dedication at no cost to Council splay corners at the intersection of Terry Road\nextension and Schofields Road to the satisfaction of Council’s Senior Coordinator\nEngineering Approvals and generally in accordance with the approved design.\n10.7.3.4 Splays are to be adjusted to meet site specific intersection designs in\naccordance with Council’s Engineering Guide for Development.\n10.7.4 Bonds/Securities/Payments in Lieu of Works\n10.7.4.1 The payment to Blacktown City Council of a monetary contribution in lieu of works for\nthe placement of the final layer of asphaltic concrete (a.c) on the new road works. The\namount will be calculated at Council's approved rate upon request and following issue\nof a Construction Certificate for the work.\n10.7.4.2 A maintenance security of 5% of the value of the required engineering works must be\nlodged with Council prior to the practical completion of the works. Council will hold\nthis security for a period of at least twelve months.\n(a) In the case of subdivision - This period commences at the release of the final\nplan of subdivision. (Issue of Subdivision Certificate)\n(b) In the case where no subdivision occurs - This period commences at the date of\npractical completion of the development.\nThis maintenance period may be extended in the following situations to allow for the\ncompletion of i) necessary maintenance and or ii) all outstanding minor works.\n10.7.4.3 Concrete path paving must not be placed until about 75% of the lots have been built\nupon or until approved in writing by Council. The applicant has the option of lodging a\nsecurity deposit for the works, or paying a monetary payment in lieu of works based\nupon Council’s Goods and Services Pricing Schedule. The security will be released\nupon satisfactory completion of the works.\n10.7.4.4 Where Council has granted approval of providing security in lieu of outstanding\nworks, a security, in the form of a bank guarantee or a cash deposit, shall be lodged\nwith Council to cover outstanding works required by this consent. The security\namount will be calculated at Council's approved rate upon request\n10.7.5 Inspection of Work\n10.7.5.1 All road stormwater drainage structures (pipelines and pits) must be inspected via\nCCTV after completion of road pavement construction works (excluding any deferred\nAC works) and the provision of all public utility services in accordance with Council’s\ncurrent Works Specification Civil. CCTV reports must be submitted to council in the\nform of video footage of the inspections, report, and a certified CCTV statement in\naccordance with section 6.8 of Council’s Works Specification Civil indicating that any\ndefects identified by this inspection have been rectified.","stage":"general","stage_basis":"heading","page":4},{"label":"11","code":null,"number":"11","title":"PRIOR TO SUBDIVISION (ENVIRONMENTAL HEALTH)","text":"11.1. Any areas potentially/contaminated shall be remediated. Upon completion of any\nrequired remediation an appropriately qualified environmental consultant shall prepare\na validation report. The validation report shall be carried out in accordance with;\n• Remedial Action Plan, (Ref: E24803.EO6_Rev 1) prepared by EI Australia, dated\n27 January 2021\n• NSW Environment Protection Authority’s Guidelines for Consultants Reporting on\nContaminated Sites (2020)\n• NSW Environment Protection Authority’s Contaminated Sites Sampling Design\nGuidelines (1995).\n• NSW Environment Protection Authority’s “Contaminated Sites: Guidelines for\nNSW Site Auditor Scheme” 3rd edition (2017)\n• National Environment Protection Council “National Environment Protection\n(Assessment of Site Contamination) Measure” (2013)","stage":"general","stage_basis":"heading","page":33}]});
